class Stack<T> {
    private T[] items;
    private int size;

    public Stack(int capacity) {
        items = new T[capacity];
    }

    public void push(T item) {
        items[size++] = item;
    }

    public T pop() {
        return items[--size];
    }
}

class Stack<T> {
    private Object[] items;
    private int size;

    public Stack(int capacity) {
        items = new Object[capacity];
    }

    public void push(T item) {
        items[size++] = item;
    }

    @SuppressWarnings("unchecked")
    public T pop() {
        return (T) items[--size];
    }
}

